def P(text, style="BodySRS"):
    return Paragraph(text, styles[style])

def table(rows, widths, header=True):
    data = [[P(str(cell), "TableHead" if header and r == 0 else "TableSRS") for cell in row] for r, row in enumerate(rows)]
    t = Table(data, colWidths=widths, repeatRows=1 if header else 0, hAlign="LEFT")
    commands = [("GRID", (0,0), (-1,-1), 0.35, colors.black), ("VALIGN", (0,0), (-1,-1), "TOP"), ("LEFTPADDING", (0,0), (-1,-1), 5), ("RIGHTPADDING", (0,0), (-1,-1), 5), ("TOPPADDING", (0,0), (-1,-1), 5), ("BOTTOMPADDING", (0,0), (-1,-1), 5)]
    if header:
        commands += [("BACKGROUND", (0,0), (-1,0), colors.HexColor("#D9E2F3"))]
    t.setStyle(TableStyle(commands))
    return t

