story += [P("1. Introduction", "H1SRS"), P("1.1 Purpose", "H2SRS"), P("This Software Requirements Specification (SRS) defines the functional and non-functional requirements for the <b>AI Powered EchoChat Application</b>. EchoChat is a web-based language-exchange and communication platform that enables users to create profiles, discover language partners, build friendships, communicate through real-time chat and video calls, and obtain multilingual help from an AI assistant."), P("This document is intended for the project team, project guide, evaluators, developers, testers, and future maintainers. It establishes the expected behaviour, interfaces, data requirements, constraints, and quality expectations of the proposed system."), P("1.2 Scope", "H2SRS"), P("EchoChat provides a unified environment for language learners who need communication practice and quick language support. The system includes secure registration and login, profile onboarding, language preferences, recommendations, friend requests, real-time one-to-one messaging, video calls, theme selection, AI chat, translation, and language detection. A language-level test and self-assessment module is included as a planned feature."), P("The frontend is developed using React and Vite. The backend uses Node.js and Express.js. MongoDB stores user and friendship information. Stream services provide real-time chat and video communication, while Gemini AI supports language-aware assistance."), P("1.3 Definitions and Abbreviations", "H2SRS"), table([["Term", "Meaning"], ["AI", "Artificial Intelligence. Gemini AI supports chat assistance, translation, and language detection."], ["JWT", "JSON Web Token used to identify an authenticated user."], ["REST API", "An HTTP-based interface through which the frontend communicates with the backend."], ["Stream", "Third-party platform integrated for real-time messaging and video calls."], ["Onboarding", "The process through which a user completes profile information after registration."], ["Friend Request", "A pending request sent by one user to another before a friendship is created."], ["Mongoose", "An Object Data Modeling library used to interact with MongoDB."]], [1.55*inch, 5.3*inch]), P("1.4 References", "H2SRS"), P("React Documentation; Express Documentation; MongoDB Documentation; Stream Chat React Documentation; Stream Video React Documentation; Google Gemini API Documentation; and RFC 7519 for JSON Web Tokens.", "PlainSRS"), PageBreak()]

story += [P("2. Overall Description", "H1SRS"), P("2.1 Product Perspective", "H2SRS"), P("EchoChat is a standalone web application based on a client-server architecture. Users interact with the React frontend in a modern browser. The frontend sends authenticated requests to the Express backend. The backend validates requests, manages session security, stores application data in MongoDB, creates Stream user tokens, and requests AI responses from Gemini when required."), P("2.2 Product Functions", "H2SRS")]
